def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if not alive_opponents:
        base = DAILY_SALARY * 0.35
        if hp <= 2 or no_water >= 1:
            base = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, base)))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= 500:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        bid = prev.get('bid') if isinstance(prev, dict) else None
        if bid is not None:
            prev_bids.append(float(bid))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    scarcity = max(0.0, min(1.0, scarcity))

    my_urgent = (hp <= 3) or (no_water >= 1)
    critical = (hp <= 2) or (no_water >= 2)

    if critical:
        bid = max(DAILY_SALARY * 1.15, highest_prev + 3.0, 82.0)
    elif my_urgent:
        bid = max(DAILY_SALARY * 0.95, avg_prev + 2.0, 68.0)
    else:
        bid = DAILY_SALARY * (0.38 + 0.22 * scarcity)
        if highest_prev >= 150:
            bid = min(bid, DAILY_SALARY * 0.42)
        elif highest_prev >= 110:
            bid = max(bid, DAILY_SALARY * 0.52)
        elif highest_prev > 0:
            bid = max(bid, min(highest_prev + 1.5, DAILY_SALARY * 0.78))

    if urgent_opp >= 2 and not my_urgent:
        bid *= 0.9
    if rich_opp >= 2 and not my_urgent:
        bid *= 0.92

    days_left = max(0, 10 - day)
    reserve_target = days_left * DAILY_SALARY * 0.42
    max_affordable_today = budget
    if not my_urgent:
        max_affordable_today = max(0.0, budget - reserve_target)
        max_affordable_today = max(max_affordable_today, DAILY_SALARY * 0.35)

    bid = min(bid, budget)
    bid = min(bid, max_affordable_today)

    if my_urgent and bid < DAILY_SALARY * 0.75:
        bid = min(budget, DAILY_SALARY * 0.75)
    if critical and bid < DAILY_SALARY * 1.0:
        bid = min(budget, DAILY_SALARY * 1.0)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', True):
            alive_opps.append(o)

    if not alive_opps:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {})
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    # Estimate a competitive target bid from yesterday's observed spending
    if prev_bids:
        highest_prev = max(prev_bids)
        # If others were bidding very high, we need a bit more to avoid losing the allocation.
        if highest_prev >= DAILY_SALARY * 0.85:
            base = DAILY_SALARY * 0.33
            if my_hp <= 3:
                base = DAILY_SALARY * 0.85
            target = base + 0.15 * highest_prev
        else:
            # Otherwise, stay near the middle to conserve budget.
            target = max(DAILY_SALARY * 0.45, (sum(prev_bids) / float(len(prev_bids))) * 0.85)
    else:
        target = DAILY_SALARY * 0.55 if my_hp > 3 else DAILY_SALARY * 0.85

    # Supply-aware adjustment: if supply is scarce, bid slightly more.
    scarcity = 0.0
    if supply <= (MIN_SUPPLY + WATER_REQ):
        scarcity = 1.0
    elif supply <= MAX_SUPPLY:
        scarcity = 0.5
    target = target * (1.0 + 0.12 * scarcity)

    # Budget and survival constraints
    # If low hp, prioritize survival.
    if my_hp <= 2.0:
        cap = my_budget
        bid = min(cap, DAILY_SALARY * 0.95)
        return max(0.0, bid)

    # Otherwise, bid but don't overspend: keep some budget for later days.
    # Aim to spend a fraction depending on how much budget remains.
    spend_fraction = 0.55
    if my_hp <= 4.0:
        spend_fraction = 0.75

    max_bid = my_budget * spend_fraction
    bid = min(float(target), float(max_bid), my_budget)

    # Ensure non-negative and not exceeding a reasonable upper bound.
    if bid < 0.0:
        bid = 0.0
    # Hard safety cap to avoid runaway bids.
    bid = min(bid, DAILY_SALARY * 1.2)
    return float(bid)

